BEGIN;

-- -------------------------------------------------------------------------------------
-- 1. EXTENSIONS (Standard Core Extensions)
-- -------------------------------------------------------------------------------------
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS "pgcrypto";

-- =====================================================================================
-- 2. AUTHENTICATION & ACCESS CONTROL (RBAC)
-- =====================================================================================

-- Table: User (Farmers, Admins, Agricultural Experts, Buyers)
CREATE TABLE IF NOT EXISTS "User" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "email" TEXT,
    "phone" TEXT,
    "passwordHash" TEXT,
    "preferredLanguage" TEXT NOT NULL DEFAULT 'en',
    "state" TEXT,
    "district" TEXT,
    "village" TEXT,
    "isDemo" BOOLEAN NOT NULL DEFAULT false,
    "experienceMode" TEXT NOT NULL DEFAULT 'simple',
    "onboardingStatus" TEXT NOT NULL DEFAULT '{}',
    "emailVerifiedAt" TIMESTAMP(3),
    "phoneVerifiedAt" TIMESTAMP(3),
    "lastLoginAt" TIMESTAMP(3),
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "User_pkey" PRIMARY KEY ("id")
);

-- Table: Role (FARMER, ADMIN, EXPERT, BUYER)
CREATE TABLE IF NOT EXISTS "Role" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "label" TEXT NOT NULL,

    CONSTRAINT "Role_pkey" PRIMARY KEY ("id")
);

-- Table: Permission (Granular RBAC capabilities)
CREATE TABLE IF NOT EXISTS "Permission" (
    "id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "group" TEXT NOT NULL,

    CONSTRAINT "Permission_pkey" PRIMARY KEY ("id")
);

-- Table: UserRole (User-to-Role Junction)
CREATE TABLE IF NOT EXISTS "UserRole" (
    "userId" TEXT NOT NULL,
    "roleId" TEXT NOT NULL,

    CONSTRAINT "UserRole_pkey" PRIMARY KEY ("userId", "roleId")
);

-- Table: RolePermission (Role-to-Permission Junction)
CREATE TABLE IF NOT EXISTS "RolePermission" (
    "roleId" TEXT NOT NULL,
    "permissionId" TEXT NOT NULL,

    CONSTRAINT "RolePermission_pkey" PRIMARY KEY ("roleId", "permissionId")
);

-- =====================================================================================
-- 3. FARMS & FIELD MANAGEMENT
-- =====================================================================================

-- Table: Farm (Agricultural landholdings)
CREATE TABLE IF NOT EXISTS "Farm" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "village" TEXT,
    "district" TEXT,
    "state" TEXT,
    "country" TEXT NOT NULL DEFAULT 'IN',
    "lat" DOUBLE PRECISION,
    "lng" DOUBLE PRECISION,
    "totalAreaHa" DOUBLE PRECISION,
    "areaInputValue" DOUBLE PRECISION,
    "areaInputUnit" TEXT DEFAULT 'acre',
    "farmType" TEXT DEFAULT 'irrigated',
    "waterSources" TEXT DEFAULT '[]',
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "Farm_pkey" PRIMARY KEY ("id")
);

-- Table: Field (Individual parcels/plots within a farm)
CREATE TABLE IF NOT EXISTS "Field" (
    "id" TEXT NOT NULL,
    "farmId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "areaHa" DOUBLE PRECISION,
    "areaSource" TEXT NOT NULL DEFAULT 'manual',
    "boundaryGeoJson" TEXT,
    "centroidLat" DOUBLE PRECISION,
    "centroidLng" DOUBLE PRECISION,
    "irrigationType" TEXT DEFAULT 'drip',
    "soilType" TEXT DEFAULT 'unknown',
    "status" TEXT NOT NULL DEFAULT 'empty',
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "Field_pkey" PRIMARY KEY ("id")
);

-- =====================================================================================
-- 4. MASTER CROPS, STAGES & ADVISORIES
-- =====================================================================================

-- Table: Crop (Master crop catalog)
CREATE TABLE IF NOT EXISTS "Crop" (
    "id" TEXT NOT NULL,
    "slug" TEXT NOT NULL,
    "category" TEXT NOT NULL DEFAULT 'cereal',
    "seasons" TEXT NOT NULL DEFAULT '[]',
    "typicalDurationDays" INTEGER,
    "displayColor" TEXT NOT NULL DEFAULT '#2F7D4F',
    "icon" TEXT DEFAULT 'sprout',
    "status" TEXT NOT NULL DEFAULT 'published',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "Crop_pkey" PRIMARY KEY ("id")
);

-- Table: CropTranslation (Multilingual crop titles & aliases: en, gu, hi)
CREATE TABLE IF NOT EXISTS "CropTranslation" (
    "id" TEXT NOT NULL,
    "cropId" TEXT NOT NULL,
    "locale" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "aliases" TEXT NOT NULL DEFAULT '[]',
    "description" TEXT,

    CONSTRAINT "CropTranslation_pkey" PRIMARY KEY ("id")
);

-- Table: CropVariety (Crop cultivars and regional hybrids)
CREATE TABLE IF NOT EXISTS "CropVariety" (
    "id" TEXT NOT NULL,
    "cropId" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "durationDays" INTEGER,
    "notes" TEXT,
    "status" TEXT NOT NULL DEFAULT 'published',

    CONSTRAINT "CropVariety_pkey" PRIMARY KEY ("id")
);

-- Table: CropStage (Phonological stages: sowing, vegetative, flowering, harvest)
CREATE TABLE IF NOT EXISTS "CropStage" (
    "id" TEXT NOT NULL,
    "cropId" TEXT NOT NULL,
    "orderIndex" INTEGER NOT NULL,
    "code" TEXT NOT NULL,
    "startOffsetDays" INTEGER NOT NULL,
    "durationDays" INTEGER NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'published',

    CONSTRAINT "CropStage_pkey" PRIMARY KEY ("id")
);

-- Table: CropStageTranslation (Localized stage names)
CREATE TABLE IF NOT EXISTS "CropStageTranslation" (
    "id" TEXT NOT NULL,
    "stageId" TEXT NOT NULL,
    "locale" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "description" TEXT,

    CONSTRAINT "CropStageTranslation_pkey" PRIMARY KEY ("id")
);

-- Table: CropStageAdvisory (Best practices per stage)
CREATE TABLE IF NOT EXISTS "CropStageAdvisory" (
    "id" TEXT NOT NULL,
    "stageId" TEXT NOT NULL,
    "activityType" TEXT NOT NULL,
    "requiresLocalConfirmation" BOOLEAN NOT NULL DEFAULT true,
    "status" TEXT NOT NULL DEFAULT 'published',

    CONSTRAINT "CropStageAdvisory_pkey" PRIMARY KEY ("id")
);

-- Table: CropStageAdvisoryTranslation (Localized advisory text)
CREATE TABLE IF NOT EXISTS "CropStageAdvisoryTranslation" (
    "id" TEXT NOT NULL,
    "advisoryId" TEXT NOT NULL,
    "locale" TEXT NOT NULL,
    "text" TEXT NOT NULL,

    CONSTRAINT "CropStageAdvisoryTranslation_pkey" PRIMARY KEY ("id")
);

-- Table: CropCycle (Active sowing cycles per field)
CREATE TABLE IF NOT EXISTS "CropCycle" (
    "id" TEXT NOT NULL,
    "fieldId" TEXT NOT NULL,
    "cropId" TEXT NOT NULL,
    "varietyId" TEXT,
    "customCropName" TEXT,
    "status" TEXT NOT NULL DEFAULT 'planned',
    "sowingDate" TIMESTAMP(3),
    "expectedHarvestDate" TIMESTAMP(3),
    "expectedHarvestBasis" TEXT DEFAULT 'estimate_from_master',
    "actualHarvestDate" TIMESTAMP(3),
    "areaHa" DOUBLE PRECISION,
    "irrigationType" TEXT,
    "seedInfo" TEXT,
    "quantityHarvested" DOUBLE PRECISION,
    "quantityUnit" TEXT DEFAULT 'kg',
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    "deletedAt" TIMESTAMP(3),

    CONSTRAINT "CropCycle_pkey" PRIMARY KEY ("id")
);

-- Table: CycleStage (Tracking actual stage progression for an active cycle)
CREATE TABLE IF NOT EXISTS "CycleStage" (
    "id" TEXT NOT NULL,
    "cropCycleId" TEXT NOT NULL,
    "templateStageId" TEXT,
    "nameSnapshot" TEXT NOT NULL,
    "startDate" TIMESTAMP(3),
    "endDate" TIMESTAMP(3),
    "orderIndex" INTEGER NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'pending',

    CONSTRAINT "CycleStage_pkey" PRIMARY KEY ("id")
);

-- =====================================================================
-- 5. OPERATIONS, TASKS & WEATHER RECORDS
-- =====================================================================

-- Table: Task (Farm operations calendar & reminders)
CREATE TABLE IF NOT EXISTS "Task" (
    "id" TEXT NOT NULL,
    "userId" TEXT NOT NULL,
    "farmId" TEXT NOT NULL,
    "fieldId" TEXT,
    "cropCycleId" TEXT,
    "type" TEXT NOT NULL DEFAULT 'custom',
    "title" TEXT NOT NULL,
    "description" TEXT,
    "dueAt" TIMESTAMP(3),
    "priority" TEXT NOT NULL DEFAULT 'medium',
    "status" TEXT NOT NULL DEFAULT 'pending',
    "source" TEXT NOT NULL DEFAULT 'manual',
