    "status" TEXT NOT NULL DEFAULT 'published',
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "AdvisoryRule_pkey" PRIMARY KEY ("id")
);

-- =====================================================================
-- 6. SOIL ANALYSIS & SCOUTING OBSERVATIONS
-- =====================================================================

